const raw = $json.body;
let d = {};
try { d = typeof raw === 'string' ? JSON.parse(raw) : (raw || {}); } catch (e) { d = {}; }
const h = $json.headers || {};
const ip = (h['cf-connecting-ip'] || h['x-forwarded-for'] || '').split(',')[0].trim();
const country = h['cf-ipcountry'] || d.country || '';
const ua = d.device || '';
const device = /iPhone|Android/i.test(ua) ? 'Phone' : /iPad/i.test(ua) ? 'Tablet' : 'Computer';
const browser = /Edg\//.test(ua) ? 'Edge' : /Chrome\//.test(ua) ? 'Chrome' : /Safari\//.test(ua) ? 'Safari' : /Firefox\//.test(ua) ? 'Firefox' : 'Other';
const when = new Date(d.time || Date.now()).toLocaleString('en-GB', { timeZone: 'Asia/Dubai' });
const who = d.email || 'unknown email';
const what = d.event === 'signin' ? 'signed in to the dashboard' : 'opened the dashboard';
const text = `Glow Up dashboard visit\n\nWho: ${who}\nWhat: ${what}\nWhen: ${when} (Dubai time)\nDevice: ${device} · ${browser} · ${d.screen || ''}\nCountry: ${country || 'n/a'}\nTimezone: ${d.tz || 'n/a'}\nIP: ${ip || 'n/a'}`;
return [{ json: { subject: `Glow Up dashboard: ${who} ${d.event === 'signin' ? 'signed in' : 'opened it'}`, text } }];
